package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TlsClientCertificateBoundAccessTokensVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property tls client certificate bound access tokens of trusted client ")
  void test_tls_client_certificate_bound_access_tokens_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> TlsClientCertificateBoundAccessTokensVO.tryFrom(null));
    Assertions.assertEquals(true, TlsClientCertificateBoundAccessTokensVO.from(true)
        .isTlsClientCertificateBoundAccessTokens());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> TlsClientCertificateBoundAccessTokensVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]",
        TlsClientCertificateBoundAccessTokensVO.from(true).toString());
  }
}
